grid = [list(map(int, line.strip().split())) for line in test_input_str.strip().split('\n')]

# Analyze frame completeness - count the "closed" nature of each frame
def analyze_frame(frame_color, grid):
    positions = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == frame_color:
                positions.append((r, c))

    # Get the bbox
    r_coords = [p[0] for p in positions]
    c_coords = [p[1] for p in positions]
    r_min, r_max = min(r_coords), max(r_coords)
    c_min, c_max = min(c_coords), max(c_coords)

    # Count perimeter vs total
    perimeter_positions = []
    for r in range(r_min, r_max + 1):
        for c in range(c_min, c_max + 1):
            if grid[r][c] == frame_color:
                perimeter_positions.append((r, c))

    filled_positions = []
    for r in range(r_min + 1, r_max):
        for c in range(c_min + 1, c_max):
            if grid[r][c] == frame_color:
                filled_positions.append((r, c))

    total = len(positions)
    perimeter = len(perimeter_positions)
    filled = len(filled_positions)

    # Ratio of perimeter to total
    perimeter_ratio = perimeter / total if total > 0 else 0

    return {
        'bbox': (r_min, r_max, c_min, c_max),
        'total': total,
        'perimeter': perimeter,
        'filled': filled,
        'perimeter_ratio': perimeter_ratio
    }

frame_info = {}
for color in [0, 3, 5, 8, 9]:
    frame_info[color] = analyze_frame(color, grid)

for color, info in frame_info.items():
    print(f"Frame {color}: {info}")

# Which frames are most "boundary-like" vs "filled"?
print("\n=== Frame boundary characterization ===")
for color, info in frame_info.items():
    if info['filled'] == 0:
        print(f"Frame {color}: PURELY PERIMETER (ratio={info['perimeter_ratio']:.1f})")
    elif info['perimeter'] > info['filled'] * 2:
        print(f"Frame {color}: BORDER-DOMINATED (ratio={info['perimeter_ratio']:.1f})")
    else:
        print(f"Frame {color}: MIXED (ratio={info['perimeter_ratio']:.1f})")

