def bboxes_adjacent(b1, b2):
    """Check if two rects (rmin, rmax, cmin, cmax) are adjacent (share an edge)"""
    r1min, r1max, c1min, c1max = b1
    r2min, r2max, c2min, c2max = b2

    # Horizontal adjacency: same rows, columns touch
    if (r1min <= r2max and r2min <= r1max and c1min <= c2max and c2min <= c1max):
        return False  # One is inside the other horizontally

    # Check four adjacency directions
    # b1 right edge == b2 left edge (and overlap in rows)
    if (c1max + 1 == c2min or c2min + 1 == c1max) and max(r1min, r2min) <= min(r1max, r2max) + 1:
        return True

    # b1 bottom edge == b2 top edge (and overlap in columns)
    if (r1max + 1 == r2min or r2max + 1 == r1min) and max(c1min, c2min) <= min(c1max, c2max) + 1:
        return True

    # Check corner adjacency
    corner_touching = False
    for (rc1, cc1) in [(r1min, c1min), (r1min, c1max), (r1max, c1min), (r1max, c1max)]:
        for (rc2, cc2) in [(r2min, c2min), (r2min, c2max), (r2max, c2min), (r2max, c2max)]:
            if (abs(rc1 - rc2) == 1 and abs(cc1 - cc2) == 1):
                corner_touching = True
                break

    return corner_touching

print("=== Frame bbox adjacency to each section ===")
for color in [0, 3, 5, 8, 9]:
    frame_bbox = get_frame_bbox(color)
    if frame_bbox is None:
