frame_ratings = {0: 0, 3: 5, 5: 5, 8: 9, 9: 8}

print("=== Output = max(frame_color, frame_rating) ===")
output = []
for sec_r in range(3):
    row = []
    for sec_c in range(3):
        sec = section_bbox(sec_r, sec_c)

        counts = {}
        for color in [0, 3, 5, 8, 9]:
            count = sum(1 for r in range(sec[0], sec[1]+1) 
                        for c in range(sec[2], sec[3]+1) 
                        if 0<=r<H and 0<=c<W and grid[r][c] == color)
            if count > 0:
                counts[color] = count

        best = max(counts.items(), key=lambda x: x[1])
        color, count = best

        # max of frame color and rating
        output_color = max(color, frame_ratings[color])
        row.append(output_color)
        print(f"Section ({sec_r},{sec_c}): {counts} -> frame {color}, rating {frame_ratings[color]} -> {output_color}")
    output.append(row)

print(f"Prediction: {output}")

